 4→  data: unknown[];
 5→  layout?: Record<string, unknown>;
 6→}
 7→
 8→export function ChartWidget({ data, layout }: ChartWidgetProps) {
 9→  // Normalize layout.title: Plotly v3 requires {text: "..."} object form
10→  const normalizedLayout = { ...layout };
11→  if (typeof normalizedLayout.title === 'string') {
12→    normalizedLayout.title = { text: normalizedLayout.title };
13→  }
14→
15→  return (
16→    <Plot
17→      data={data as Plotly.Data[]}
18→      layout={{ autosize: true, height: 400, ...normalizedLayout } as Partial<Plotly.Layout>}
19→      useResizeHandler
20→      style={{ width: '100%' }}
21→      config={{ responsive: true, displayModeBar: true }}
