          { "label": "2020", "method": "animate", "args": [["2020"], { "frame": { "duration": 800, "redraw": true }, "transition": { "duration": 400 } }] }
        ]
      }
    ]
  },
  "frames": [
    {
      "name": "2000",
      "data": [{ "x": [10, 20, 30, 40, 50], "y": [5000, 8000, 12000, 15000, 20000], "marker": { "size": [20, 25, 30, 35, 40], "color": [100, 200, 300, 400, 500] } }]
    },
    {
      "name": "2005",
      "data": [{ "x": [15, 25, 35, 42, 52], "y": [6000, 9000, 13000, 16000, 22000], "marker": { "size": [22, 27, 28, 37, 42], "color": [150, 250, 350, 450, 550] } }]
    },
    {
      "name": "2010",
      "data": [{ "x": [20, 30, 38, 45, 53], "y": [7500, 10000, 14000, 18000, 25000], "marker": { "size": [25, 30, 26, 40, 45], "color": [200, 300, 400, 500, 600] } }]
    },
    {
      "name": "2015",
      "data": [{ "x": [25, 33, 40, 47, 55], "y": [9000, 11000, 15000, 20000, 28000], "marker": { "size": [28, 32, 25, 42, 48], "color": [250, 350, 450, 550, 650] } }]
    },
    {
      "name": "2020",
      "data": [{ "x": [30, 36, 43, 50, 56], "y": [10000, 12000, 16000, 22000, 32000], "marker": { "size": [30, 35, 24, 45, 50], "color": [300, 400, 500, 600, 700] } }]
    }
  ]
}
```

**Key animation features:**

- **`frames`** — each frame represents a time step (year 2000-2020) with updated data
- **`updatemenus`** — Play/Pause buttons that trigger `method: "animate"`
- **`sliders`** — a scrubber bar to jump between frames
- **`transition.duration`** — smooth interpolation between frames (400ms cubic-in-out easing)
- **`frame.duration`** — how long each frame displays (800ms)

**Note on your ChartWidget:** The current `ChartWidget` component only passes `data` and `layout` to `<Plot>`. To support animation, you'd also need to pass `frames` as a prop:

```tsx
<Plot
  data={data}
  layout={layout}
  frames={frames}  // <-- needed for animation
  config={{ responsive: true, displayModeBar: true }}
/>
```

Without passing `frames`, the chart will render the initial `data` trace statically. Want me to update the `ChartWidget` component to support animated charts?

